import test from 'node:test';import assert from 'node:assert/strict';import vm from'node:vm';import{readFileSync}from'node:fs';
const html=readFileSync(new URL('../../index.html',import.meta.url),'utf8');
function source(name){const start=html.indexOf('function '+name+'(');assert.ok(start>=0,name);let depth=0,quote=null;for(let i=html.indexOf('{',start);i<html.length;i++){const c=html[i];if(quote){if(c===quote&&html[i-1]!=='\\')quote=null;continue;}if(c==='"'||c==="'"){quote=c;continue;}if(c==='/'&&html[i+1]==='/'){i=html.indexOf('\n',i);continue;}if(c==='/'&&html[i+1]==='*'){i=html.indexOf('*/',i)+1;continue;}if(c==='{')depth++;else if(c==='}'&&--depth===0)return html.slice(start,i+1);}throw new Error('source '+name);}
const names=['escapeHtml','reporterStatsNameAllowed','reporterStatsContextAllowed','reporterStatsElement','reporterStatsRememberEntry','reporterStatsContextForEntry','buildReportSearchIndex','reporterStatsHistoryHtml','reporterStatsCounts','closeReporterStats','reporterStatsStillCurrent','openReporterStats','reporterStatsKeydown','renderReportResults'];
function fixture(){let context;class Node{constructor(tag){this.tag=tag;this.children=[];this.dataset={};this.style={};this.attributes={};this.isConnected=true;this.value='';}set textContent(x){this.value=String(x);this.children=[];}get textContent(){return this.value+this.children.map(x=>x.textContent).join('');}appendChild(n){this.children.push(n);return n;}setAttribute(k,v){this.attributes[k]=v;}getClientRects(){return this.isConnected?[{}]:[];}focus(){context.document.activeElement=this;}}
const nodes=Object.fromEntries(['reporterStatsModal','reporterStatsContent','reporterStatsClose'].map(id=>[id,new Node('div')]));const classes=new Set(),calls=[];context={URLSearchParams,Number,Object,Promise,MutationObserver:class{observe(){}disconnect(){}},reporterStatsRequest:0,reporterStatsData:null,reporterStatsOwner:null,reporterStatsObserver:null,reporterStatsWitnesses:new WeakMap(),reportFixedHistory:{},reportSearchIndex:[],publicationState:{generation:1},permission:true,document:{nodes,activeElement:null,body:{classList:{add:c=>classes.add(c),remove:c=>classes.delete(c)}},getElementById:id=>nodes[id],createElement:tag=>new Node(tag)},publicationAllowed:()=>context.permission,publicationDataAllowed:()=>context.permission,openReportEntry(){},resultSectionTitle(){return new Node('div');},reportEntryPlace:()=>'',publicationFetch:path=>{let resolve,reject;const p=new Promise((a,b)=>{resolve=a;reject=b;});calls.push({path,resolve,reject});return p;}};vm.createContext(context);vm.runInContext(names.map(source).join('\n'),context);const trigger=(name='합성검증')=>context.reporterStatsElement(name,{source:'history',reportId:'11111111-1111-4111-8111-111111111111'},false);return {c:context,nodes,classes,calls,trigger,Node};}
const plain=x=>JSON.parse(JSON.stringify(x));
test('normal two count types zero and multi species accepted',()=>{const f=fixture();for(const x of [{speciesCount:0,reportCount:0},{speciesCount:6,reportCount:3}])assert.deepEqual(plain(f.c.reporterStatsCounts(x)),x);});
test('numeric coercion and unexpected private fields rejected',()=>{const {c}=fixture();for(const n of [null,undefined,NaN,Infinity,-1,0.5,'3',true])assert.equal(c.reporterStatsCounts({speciesCount:n,reportCount:1}),null);for(const x of [{speciesCount:1,reportCount:0},{speciesCount:1,reportCount:1,lat:37},{speciesCount:1,reportCount:1,reporter:'비공개'}])assert.equal(c.reporterStatsCounts(x),null);assert.equal(c.reporterStatsCounts(Object.create({speciesCount:1,reportCount:1})),null);});
test('anonymous blank missing witness never clickable',()=>{const f=fixture();for(const name of [null,undefined,'','   ','x'.repeat(41)])assert.notEqual(f.c.reporterStatsElement(name,{source:'history',reportId:'id'},true).className,'reporterStatsLink');assert.notEqual(f.c.reporterStatsElement('일반공개',{source:'search'},true).className,'reporterStatsLink');assert.equal(f.c.reporterStatsHistoryHtml({reporter:''}),'익명 제보');});
test('nickname identity retained literally and escaped history button',()=>{const f=fixture(),name='Bird "<safe>"';const n=f.trigger(name);assert.equal(n.dataset.reporter,name);assert.match(f.c.reporterStatsHistoryHtml({id:'id1',reporter:name}),/&quot;&lt;safe&gt;&quot;/);});
test('actual search renderer does not promote anonymous label to nickname',()=>{const f=fixture(),box=new f.Node('div');f.c.renderReportResults(box,[{reportId:'id1',reporter:'',species:['合成']}]);const visit=n=>[n,...n.children.flatMap(visit)];assert.equal(visit(box).filter(n=>n.className==='reporterStatsLink').length,0);});
test('open calls P1 transport only and shows two fields',async()=>{const f=fixture(),p=f.c.openReporterStats(f.trigger());assert.ok(f.calls[0].path.startsWith('/reports/reporter-stats?'));assert.equal(new URL('https://test'+f.calls[0].path).searchParams.get('reporter'),'합성검증');f.calls[0].resolve({speciesCount:3,reportCount:2});assert.equal(await p,true);assert.equal(f.nodes.reporterStatsContent.textContent,'누적 출현종 수3종승인 제보 건수2건');assert.equal(f.c.document.activeElement,f.nodes.reporterStatsClose);});
test('late A cannot overwrite newer B',async()=>{const f=fixture(),a=f.c.openReporterStats(f.trigger('A')),b=f.c.openReporterStats(f.trigger('B'));f.calls[1].resolve({speciesCount:4,reportCount:2});assert.equal(await b,true);f.calls[0].resolve({speciesCount:99,reportCount:99});assert.equal(await a,false);assert.equal(f.nodes.reporterStatsContent.textContent,'누적 출현종 수4종승인 제보 건수2건');});
test('close clears counts and references and late reply remains closed',async()=>{const f=fixture(),trigger=f.trigger(),p=f.c.openReporterStats(trigger);f.c.closeReporterStats(true);f.calls[0].resolve({speciesCount:7,reportCount:3});assert.equal(await p,false);assert.equal(f.nodes.reporterStatsModal.style.display,'none');assert.equal(f.nodes.reporterStatsContent.textContent,'');assert.equal(f.c.reporterStatsOwner,null);assert.equal(f.c.reporterStatsData,null);assert.equal(f.c.document.activeElement,trigger);});
test('different publication generation cannot display response',async()=>{const f=fixture(),p=f.c.openReporterStats(f.trigger());f.c.publicationState.generation++;f.calls[0].resolve({speciesCount:8,reportCount:5});assert.equal(await p,false);assert.equal(f.c.reporterStatsData,null);});
test('permission failure and disconnected trigger never restore payload',async()=>{for(const change of ['permission','disconnected']){const f=fixture(),trigger=f.trigger(),p=f.c.openReporterStats(trigger);if(change==='permission')f.c.permission=false;else trigger.isConnected=false;f.calls[0].resolve({speciesCount:8,reportCount:5});assert.equal(await p,false);assert.equal(f.c.reporterStatsData,null);}});
test('fetch error does not expose input or restore old statistics',async()=>{const f=fixture(),p=f.c.openReporterStats(f.trigger('Public Name'));f.calls[0].reject(new Error('synthetic-error-sensitive-metadata'));assert.equal(await p,false);assert.ok(!f.nodes.reporterStatsContent.textContent.includes('Public Name'));assert.ok(!f.nodes.reporterStatsContent.textContent.includes('metadata'));assert.equal(f.c.reporterStatsData,null);});
test('Tab remains in own dialog and close does not clear parent modal class',()=>{const f=fixture();f.classes.add('monthTideOpen');let prevented=false;f.c.reporterStatsKeydown({key:'Tab',preventDefault(){prevented=true;}});assert.ok(prevented);f.c.closeReporterStats(false);assert.ok(f.classes.has('monthTideOpen'));});
test('source hooks close statistic synchronously on P1 barrier',()=>{assert.match(source('publicationInvalidate'),/closeReporterStats\(false\)/);assert.ok(html.includes("node.contains(reporterStatsOwner))closeReporterStats(false)"));assert.ok(html.includes("reporterStatsOwner&&!reporterStatsOwner.isConnected"));});

test('existing search DTO keys preserved with exact transient source id',()=>{const f=fixture();f.c.buildReportSearchIndex([{id:'spot',lat:37,lon:127,history:[{id:'report1',date:'2026-10-14',reporter:'공개검증',species:['까치']}]}]);const row=f.c.reportSearchIndex[0];assert.deepEqual(Object.keys(row).sort(),['date','kind','lat','lon','reporter','species','spotId']);assert.equal(f.c.reporterStatsContextForEntry(row).reportId,'report1');});


test('P1 clears site history DOM and retained loaded aliases including closed popup',()=>{
 const loaded=[{reporter:'Synthetic name'}],list={className:'',textContent:'Synthetic name'},badge={textContent:'1'};
 const box={_birdmapLoaded:loaded,querySelector:q=>q==='.siteHistoryList'?list:badge};
 const root={querySelectorAll:()=>[box]};
 const c={document:{querySelectorAll:()=>[]},markerRegistry:{one:{getPopup:()=>({getContent:()=>root,getElement:()=>null})}}};
 vm.createContext(c);vm.runInContext(source('clearRenderedSiteHistories'),c);c.clearRenderedSiteHistories();
 assert.equal(loaded.length,0);assert.equal(box._birdmapLoaded.length,0);assert.ok(!list.textContent.includes('Synthetic'));assert.equal(badge.textContent,'');
});
test('history final renderer rejects unverified or disconnected payload without mutation',()=>{
 const box={};const c={document:{body:{contains:()=>true}},siteHistoryBoxIn:()=>box,publicationDataAllowed:()=>false};vm.createContext(c);vm.runInContext(source('renderSiteHistory'),c);c.renderSiteHistory(box,{}, {history:[{reporter:'Synthetic'}]},{});assert.equal(box._birdmapLoaded,undefined);
 c.publicationDataAllowed=()=>true;c.document.body.contains=()=>false;c.renderSiteHistory(box,{}, {history:[{reporter:'Synthetic'}]},{});assert.equal(box._birdmapLoaded,undefined);
});
